16	/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
17	/// [restoreSession] is unconditional — no client-side expiry math — and
18	/// covers the I/O matrix (spec-1-4):
19	/// - no stored refresh token -> no network call, emits `unauthenticated`
20	///   immediately.
21	/// - stored token, backend accepts -> new pair persisted via `saveSession`,
22	///   emits `authenticated`.
23	/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
24	///   token) -> `clearSession`, emits `unauthenticated`.
25	/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
26	///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
27	///   retries naturally.
28	class SessionRepositoryImpl implements SessionRepository {
29	  SessionRepositoryImpl({
30	    required AuthRemoteDataSource remoteDataSource,
31	    required AccessTokenProvider accessTokenProvider,
32	    required SessionExpiryNotifier sessionExpiryNotifier,
33	  }) : _remoteDataSource = remoteDataSource,
34	       _accessTokenProvider = accessTokenProvider,
35	       _sessionExpiryNotifier = sessionExpiryNotifier {
36	    // Story 1.5 — the one bridge from `core`'s expiry signal onto this
37	    // feature's own `SessionStatus` stream (Design Notes). Subscribed for
38	    // this repository's whole lifetime; cancelled in [dispose].
39	    _expirySubscription = _sessionExpiryNotifier.expiredEvents.listen(
40	      (_) => _onSessionExpired(),
41	    );
42	  }
43	
44	  final AuthRemoteDataSource _remoteDataSource;
45	  final AccessTokenProvider _accessTokenProvider;
46	  final SessionExpiryNotifier _sessionExpiryNotifier;
47	  late final StreamSubscription<void> _expirySubscription;
48	  final StreamController<SessionStatus> _statusController =
49	      StreamController<SessionStatus>.broadcast();
50	
51	  /// The last status emitted, so a consumer that subscribes *after* the
52	  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
53	  /// listener) still sees current state immediately rather than nothing
54	  /// until the next change — see [statusStream].
55	  SessionStatus? _lastStatus;
56	
57	  @override
58	  Stream<SessionStatus> get statusStream {
59	    // `Stream.multi` runs this callback once per listener (and, with
60	    // `isBroadcast: true`, supports more than one simultaneously) — each
61	    // new listener synchronously gets the cached last status (if any)
62	    // before being attached to the live broadcast controller for whatever
63	    // comes next. This is this story's whole reason to not just expose
64	    // `_statusController.stream` directly: a plain broadcast stream only
65	    // ever delivers *future* events to a listener that joins late.
66	    return Stream<SessionStatus>.multi((controller) {
67	      final last = _lastStatus;
68	      if (last != null) {
69	        controller.add(last);
70	      }
71	      final subscription = _statusController.stream.listen(
72	        controller.add,
73	        onError: controller.addError,
74	        onDone: controller.close,
75	      );
76	      controller.onCancel = subscription.cancel;
77	    }, isBroadcast: true);
78	  }
79	
80	  void _emit(SessionStatus status) {
81	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
82	    // an in-flight `restoreSession()` call — without this, a late `.add()`
83	    // after `.close()` would throw an unhandled `StateError` instead of
84	    // just being a no-op on an already-torn-down repository.
85	    if (_statusController.isClosed) {
86	      return;
87	    }
88	    _lastStatus = status;
89	    _statusController.add(status);
90	  }
91	
92	  /// "Always" boundary — a mid-session expiry only ever matters while the
93	  /// user is currently [SessionStatus.authenticated]; any other current
94	  /// status (not yet decided at boot, already unauthenticated/logged out,
95	  /// or already [SessionStatus.expired] from an earlier event) is a
96	  /// silent no-op — covers both the "expiry while not authenticated"
97	  /// post-logout race and the "already-open overlay" double-event case in
98	  /// the I/O matrix (a second event here never re-emits once [_lastStatus]
99	  /// is already [SessionStatus.expired]).
100	  void _onSessionExpired() {
101	    if (_lastStatus == SessionStatus.authenticated) {
102	      _emit(SessionStatus.expired);
103	    }
104	  }
105	
106	  @override
107	  Future<Either<Failure, Unit>> restoreSession() async {
108	    String? refreshToken;
109	    try {
110	      refreshToken = await _accessTokenProvider.readRefreshToken();
111	    } catch (error) {
112	      // A thrown platform exception from the native secure-storage channel
113	      // must never escape unmapped (RNF09) — fail closed, same as any other
114	      // unreadable session.
115	      _emit(SessionStatus.unauthenticated);
116	      return left(Failure.malformedResponse(message: error.toString()));
117	    }
118	
119	    if (refreshToken == null || refreshToken.isEmpty) {
120	      // Fresh install / post-logout (null), or a stored-but-empty token
121	      // (the backend response schema has no `minLength` on `refreshToken`,
122	      // so an empty string is a theoretically valid stored value) — either
123	      // way, no network call: `auth-refresh`'s own request schema requires
124	      // `minLength: 1`, so an empty token would only fail server-side.
125	      _emit(SessionStatus.unauthenticated);
126	      return left(
127	        const Failure.authExpired(message: 'No stored session to restore'),
128	      );
129	    }
130	
131	    final result = await _remoteDataSource.refresh(refreshToken);
132	    return result.match(
133	      (failure) async {
134	        // Only a backend-confirmed dead token clears storage; any other
135	        // failure (offline, timeout, malformed response, ...) leaves it
136	        // untouched so the next boot retries naturally.
137	        if (failure is AuthExpired || failure is AuthInvalid) {
138	          try {
139	            await _accessTokenProvider.clearSession();
140	          } catch (_) {
141	            // Best-effort clear — the session is already being treated as
142	            // unauthenticated below regardless of whether this succeeds.
143	          }
144	        }
145	        _emit(SessionStatus.unauthenticated);
146	        return left(failure);
147	      },
148	      (session) async {
149	        try {
150	          await _accessTokenProvider.saveSession(
151	            accessToken: session.accessToken,
152	            refreshToken: session.refreshToken,
153	          );
154	        } catch (error) {
155	          _emit(SessionStatus.unauthenticated);
156	          return left(Failure.malformedResponse(message: error.toString()));
157	        }
158	        _emit(SessionStatus.authenticated);
159	        return right(unit);
160	      },
161	    );
162	  }
163	
164	  @override
165	  Future<void> dispose() async {
166	    await _expirySubscription.cancel();
167	    await _statusController.close();
168	  }
169	}
