30	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
31	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
32	/// epic's UX constraints).
33	///
34	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
35	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
36	/// boot (unconditional, no client-side expiry math) and the stream's first
37	/// emission decides whether the user lands on `AuthScreen` or the post-auth
38	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
39	/// shape is unchanged, and a successful signup/login still simply
40	/// pushes-replaces via `onAuthenticated`.
41	///
42	/// Story 1.5 scope: a mid-session expiry (the same stream's `expired`
43	/// value) never changes which screen `home` renders — `build()`'s
44	/// `StreamBuilder` branch below treats it identically to `authenticated`.
45	/// The only extra reaction is scheduling the `ConfirmationDialog` overlay
46	/// on top of that same screen, from inside that same (sole) subscription —
47	/// `SessionRepository.statusStream`'s real implementation is a broadcast
48	/// `Stream.multi`, but several existing tests mock it as a plain
49	/// single-subscription `Stream.value(...)`, so a *second* independent
50	/// `.listen()` here would break those by listening to it twice.
51	class CerneApp extends StatefulWidget {
52	  const CerneApp({super.key});
53	
54	  @override
55	  State<CerneApp> createState() => _CerneAppState();
56	}
57	
58	class _CerneAppState extends State<CerneApp> {
59	  late final SessionRepository _sessionRepository;
60	
61	  // Cached once: `SessionRepository.statusStream`'s getter builds a new
62	  // `Stream.multi` instance on every access (code review of
63	  // story-1-4-silent-session-refresh-persistence), so reading it straight
64	  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
65	  // and lose its current status on each rebuild instead of staying on one
66	  // subscription for this widget's lifetime.
67	  late final Stream<SessionStatus> _statusStream;
68	
69	  @override
70	  void initState() {
71	    super.initState();
72	    _sessionRepository = sl<SessionRepository>();
73	    _statusStream = _sessionRepository.statusStream;
74	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
75	    // below, not through this call's return value. `restoreSession()`
76	    // already maps every internal failure to `Left`/an `unauthenticated`
77	    // emission and never throws. This `catchError` is NOT a UI recovery
78	    // path — its handler's return value is discarded by `unawaited` and
79	    // never reaches `statusStream`, so it does not unblock `build()`'s
80	    // `_BootLoadingScreen` branch. It exists purely so a future regression
81	    // that broke the "never throws" contract above would surface as a
82	    // logged message instead of an unhandled zone exception.
83	    unawaited(
84	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
85	    );
86	  }
87	
88	  /// Story 1.5's whole reaction to an `expired` snapshot (I/O matrix —
89	  /// every other status is a no-op, since `SessionRepositoryImpl` already
90	  /// only ever emits `expired` from `authenticated`, and this is called
91	  /// from the same `StreamBuilder` subscription that renders the screen,
92	  /// not a second one).
93	  ///
94	  /// `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a route,
95	  /// which must never happen mid-`build()` — deferred to
96	  /// `addPostFrameCallback`. Safe to call on every rebuild that still sees
97	  /// `expired` (not only the first): `ConfirmationDialog.show`'s own
98	  /// single-overlay guard makes every call after the first a no-op.
99	  void _maybeShowExpiryOverlay(BuildContext context, SessionStatus? status) {
100	    if (status != SessionStatus.expired) {
101	      return;
102	    }
103	    WidgetsBinding.instance.addPostFrameCallback((_) {
104	      if (!context.mounted) {
105	        return;
106	      }
107	      ConfirmationDialog.show(
108	        context: context,
109	        builder: (dialogContext) => ConfirmationDialog(
110	          icon: Icons.lock_outline,
111	          title: 'Sessão expirada',
112	          message:
113	              'Sua sessão expirou por segurança. Entre novamente para '
114	              'continuar — sua conversa continua aqui.',
115	          caption: 'o histórico e a posição do scroll são preservados',
116	          confirmLabel: 'Entrar novamente',
117	          barrierColor: DesignTokens.colorScrim,
118	          onConfirm: () {
119	            Navigator.of(dialogContext).pop();
120	            Navigator.of(context).push(
121	              MaterialPageRoute(
122	                builder: (_) => const _BiometricReauthPlaceholder(),
123	              ),
124	            );
125	          },
126	        ),
127	      );
128	    });
129	  }
130	
131	  // `catchError`'s handler must still complete the Future with a value of
132	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
133	  // handler would try to complete it with `null`, which isn't assignable
134	  // to that non-nullable type and would itself throw.
135	  static Either<Failure, Unit> _asUnauthenticated(
136	    Object error,
137	    StackTrace stackTrace,
138	  ) {
139	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
140	    return left(Failure.malformedResponse(message: error.toString()));
141	  }
142	
143	  @override
144	  Widget build(BuildContext context) {
145	    return MaterialApp(
146	      debugShowCheckedModeBanner: false,
147	      home: StreamBuilder<SessionStatus>(
148	        stream: _statusStream,
149	        builder: (context, snapshot) {
150	          if (!snapshot.hasData) {
151	            // No emission yet: brief-blank for the happy path (RNF01's
152	            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
153	            // spinner once the wait actually crosses that.
154	            return const _BootLoadingScreen();
155	          }
156	          // Story 1.5: `expired` renders the exact same screen as
157	          // `authenticated` — the recovery overlay is layered on top
158	          // (scheduled below) instead of this branch ever returning a
159	          // different widget for it (Boundaries: "the authenticated
160	          // screen's widget instance is never replaced across
161	          // authenticated<->expired transitions").
162	          if (snapshot.data == SessionStatus.authenticated ||
163	              snapshot.data == SessionStatus.expired) {
164	            _maybeShowExpiryOverlay(context, snapshot.data);
165	            return const _PostAuthPlaceholder();
166	          }
167	          return AuthScreen(
168	            cubit: sl<AuthCubit>(),
169	            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
170	              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
171	            ),
172	          );
173	        },
174	      ),
175	    );
176	  }
177	}
