12	import '../session/session_expiry_notifier.dart';
13	
14	/// The project's single `get_it` instance — exactly one DI container exists
15	/// (architecture spine). Every feature's `registerXFeature()` registers
16	/// through this same `sl`, never a second container.
17	final sl = GetIt.instance;
18	
19	/// Bootstraps core infrastructure: loads `.env`, then registers
20	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
21	/// interceptors) and `ApiClient` through `sl` — the `dio` +
22	/// `flutter_secure_storage` + `get_it` integration spike this story proves
23	/// before anything else is built on top of it.
24	Future<void> setupCoreDependencies() async {
25	  await dotenv.load(fileName: '.env');
26	
27	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
28	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
29	
30	  sl.registerLazySingleton<FlutterSecureStorage>(
31	    () => const FlutterSecureStorage(),
32	  );
33	
34	  sl.registerLazySingleton<AccessTokenProvider>(
35	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
36	  );
37	
38	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
39	
40	  // Story 1.5 — registered before `ApiClient` so it's ready to inject;
41	  // `dispose:` wires `SessionExpiryNotifier.dispose()` into `get_it`'s own
42	  // reset lifecycle, same rationale as `SessionRepository`'s own
43	  // registration below.
44	  sl.registerLazySingleton<SessionExpiryNotifier>(
45	    () => SessionExpiryNotifierImpl(),
46	    dispose: (notifier) => notifier.dispose(),
47	  );
48	
49	  sl.registerLazySingleton<Dio>(() {
50	    final dio = Dio(
51	      BaseOptions(
52	        // Design note (docs/input is silent on exact numbers): a stalled
53	        // connection must still fail instead of hanging indefinitely.
54	        connectTimeout: const Duration(seconds: 10),
55	        receiveTimeout: const Duration(seconds: 30),
56	        sendTimeout: const Duration(seconds: 30),
57	      ),
58	    );
59	    dio.interceptors.add(
60	      HeaderInterceptor(
61	        anonKey: supabaseAnonKey,
62	        accessTokenProvider: sl<AccessTokenProvider>(),
63	      ),
64	    );
65	    dio.interceptors.add(RetryInterceptor(dio));
66	    return dio;
67	  });
68	
69	  sl.registerLazySingleton<ApiClient>(
70	    () => ApiClient(
71	      dio: sl<Dio>(),
72	      urlBuilder: sl<UrlBuilder>(),
73	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
74	    ),
75	  );
76	
77	  registerAuthFeature();
78	}
79	
80	/// Test/teardown helper — resets the single `get_it` instance so each test
81	/// bootstraps its own clean registrations.
82	Future<void> resetCoreDependencies() => sl.reset();
