15	/// Every other network test (`api_client_test.dart`, `header_interceptor_test.dart`,
16	/// `retry_interceptor_test.dart`) mocks `Dio` itself or drives one interceptor
17	/// in isolation — neither proves the pieces work *wired together* the way
18	/// `setupCoreDependencies` actually wires them (AD-5), nor that a retry
19	/// genuinely goes back out over the wire.
20	///
21	/// Like `bootstrap_integration_test.dart` fakes the native secure-storage
22	/// channel (no device/CI exists yet to do otherwise), this fakes only the
23	/// transport boundary (`HttpClientAdapter`) — everything above it (URL
24	/// building, both real interceptors, `ApiClient`'s mapping) is the genuine
25	/// production wiring.
26	class _FakeHttpClientAdapter implements HttpClientAdapter {
27	  final List<RequestOptions> requests = [];
28	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
29	
30	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
31	    _queue.add((statusCode: statusCode, body: body));
32	  }
33	
34	  @override
35	  Future<ResponseBody> fetch(
36	    RequestOptions options,
37	    Stream<Uint8List>? requestStream,
38	    Future<void>? cancelFuture,
39	  ) async {
40	    requests.add(options);
41	    if (_queue.isEmpty) {
42	      throw StateError(
43	        'No queued response for ${options.method} ${options.path}',
44	      );
45	    }
46	    final next = _queue.removeAt(0);
47	    return ResponseBody.fromString(
48	      jsonEncode(next.body),
49	      next.statusCode,
50	      headers: {
51	        Headers.contentTypeHeader: [Headers.jsonContentType],
52	      },
53	    );
54	  }
55	
56	  @override
57	  void close({bool force = false}) {}
58	}
