60	/// A minimal, real (non-mocked) in-memory implementation — this suite is
61	/// about proving the wiring, not re-verifying token-storage behavior
62	/// (already covered by `access_token_provider_test.dart`).
63	class _InMemoryAccessTokenProvider implements AccessTokenProvider {
64	  String? _token;
65	  String? _refreshToken;
66	
67	  @override
68	  Future<String?> readAccessToken() async => _token;
69	
70	  @override
71	  Future<void> saveAccessToken(String token) async => _token = token;
72	
73	  @override
74	  Future<void> clearAccessToken() async => _token = null;
75	
76	  @override
77	  Future<String?> readRefreshToken() async => _refreshToken;
78	
79	  @override
80	  Future<void> saveSession({
81	    required String accessToken,
82	    required String refreshToken,
83	  }) async {
84	    _token = accessToken;
85	    _refreshToken = refreshToken;
86	  }
87	
88	  @override
89	  Future<void> clearSession() async {
90	    _token = null;
91	    _refreshToken = null;
92	  }
93	}
