41	    switch (call.method) {
42	      case 'write':
43	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
44	        return null;
45	      case 'read':
46	        return fakeNativeStorage[args['key'] as String];
47	      case 'delete':
48	        fakeNativeStorage.remove(args['key'] as String);
49	        return null;
50	      case 'containsKey':
51	        return fakeNativeStorage.containsKey(args['key'] as String);
52	      default:
