// `accessTokenProvider`) distinct from the private fields they initialize,
// matching `auth_repository_impl.dart`'s documented convention.
// ignore_for_file: prefer_initializing_formals
import 'dart:async';

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../../../../core/network/access_token_provider.dart';
import '../../domain/entities/session_status.dart';
import '../../domain/repositories/session_repository.dart';
import '../datasources/auth_remote_data_source.dart';

/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
/// [restoreSession] is unconditional — no client-side expiry math — and
/// covers the I/O matrix (spec-1-4):
/// - no stored refresh token -> no network call, emits `unauthenticated`
///   immediately.
/// - stored token, backend accepts -> new pair persisted via `saveSession`,
///   emits `authenticated`.
/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
///   token) -> `clearSession`, emits `unauthenticated`.
/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
///   retries naturally.
class SessionRepositoryImpl implements SessionRepository {
  SessionRepositoryImpl({
    required AuthRemoteDataSource remoteDataSource,
    required AccessTokenProvider accessTokenProvider,
  }) : _remoteDataSource = remoteDataSource,
       _accessTokenProvider = accessTokenProvider;

  final AuthRemoteDataSource _remoteDataSource;
  final AccessTokenProvider _accessTokenProvider;
  final StreamController<SessionStatus> _statusController =
      StreamController<SessionStatus>.broadcast();

  /// The last status emitted, so a consumer that subscribes *after* the
  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
  /// listener) still sees current state immediately rather than nothing
  /// until the next change — see [statusStream].
  SessionStatus? _lastStatus;

  @override
  Stream<SessionStatus> get statusStream {
    // `Stream.multi` runs this callback once per listener (and, with
    // `isBroadcast: true`, supports more than one simultaneously) — each
    // new listener synchronously gets the cached last status (if any)
    // before being attached to the live broadcast controller for whatever
    // comes next. This is this story's whole reason to not just expose
    // `_statusController.stream` directly: a plain broadcast stream only
    // ever delivers *future* events to a listener that joins late.
    return Stream<SessionStatus>.multi((controller) {
      final last = _lastStatus;
      if (last != null) {
        controller.add(last);
      }
      final subscription = _statusController.stream.listen(
        controller.add,
        onError: controller.addError,
        onDone: controller.close,
      );
      controller.onCancel = subscription.cancel;
    }, isBroadcast: true);
  }

  void _emit(SessionStatus status) {
    _lastStatus = status;
    _statusController.add(status);
  }

  @override
  Future<Either<Failure, Unit>> restoreSession() async {
    String? refreshToken;
    try {
      refreshToken = await _accessTokenProvider.readRefreshToken();
    } catch (error) {
      // A thrown platform exception from the native secure-storage channel
      // must never escape unmapped (RNF09) — fail closed, same as any other
      // unreadable session.
      _emit(SessionStatus.unauthenticated);
      return left(Failure.malformedResponse(message: error.toString()));
    }

    if (refreshToken == null) {
      // Fresh install / post-logout: no network call at all.
      _emit(SessionStatus.unauthenticated);
      return left(
        const Failure.authExpired(message: 'No stored session to restore'),
      );
    }

    final result = await _remoteDataSource.refresh(refreshToken);
    return result.match(
      (failure) async {
        // Only a backend-confirmed dead token clears storage; any other
        // failure (offline, timeout, malformed response, ...) leaves it
        // untouched so the next boot retries naturally.
        if (failure is AuthExpired || failure is AuthInvalid) {

import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// The port [HeaderInterceptor] reads the current user's access token
/// through. Owned by `core/` (not a feature) since the header-policy rule
/// (AD-5) is core infrastructure; the `auth` feature calls
/// [saveAccessToken]/[clearAccessToken] on login/logout (Story 1.3) and
/// [saveSession]/[readRefreshToken]/[clearSession] for refresh-token
/// persistence (Story 1.4) without this contract's existing three methods
/// changing.
abstract class AccessTokenProvider {
  Future<String?> readAccessToken();

  Future<void> saveAccessToken(String token);

  Future<void> clearAccessToken();

  /// Reads the refresh token persisted by [saveSession], or `null` if none
  /// is stored (fresh install / post-logout / post-clear).
  Future<String?> readRefreshToken();

  /// Persists both halves of a session pair in one call — used after
  /// signup/login/refresh so the access and refresh tokens are never saved
  /// out of step with each other.
  Future<void> saveSession({
    required String accessToken,
    required String refreshToken,
  });

  /// Clears both the access and refresh tokens — used when the backend
  /// reports the stored refresh token is dead (`AUTH_EXPIRED`/`AUTH_INVALID`).
  Future<void> clearSession();
}

/// Default implementation, backed by `flutter_secure_storage` — the same
/// package this story's DI bootstrap integration test proves works end to
/// end through `get_it`.
class SecureStorageAccessTokenProvider implements AccessTokenProvider {
  SecureStorageAccessTokenProvider(this._storage);

  static const _key = 'user_access_token';

  /// New key, alongside [_key], for the refresh token (Story 1.4).
  static const _refreshKey = 'user_refresh_token';

  final FlutterSecureStorage _storage;

  @override
  Future<String?> readAccessToken() => _storage.read(key: _key);

  @override
  Future<void> saveAccessToken(String token) =>
      _storage.write(key: _key, value: token);

  @override
  Future<void> clearAccessToken() => _storage.delete(key: _key);

  @override
  Future<String?> readRefreshToken() => _storage.read(key: _refreshKey);

  @override
  Future<void> saveSession({
    required String accessToken,
    required String refreshToken,
  }) async {
    // Refresh token first: these are two independent sequential writes
    // (no atomic multi-key transaction in `flutter_secure_storage`), so if
    // the second write below ever fails, this order leaves the *refresh*
    // token as the backend's latest-issued one — the next boot's
    // `restoreSession()` self-heals from it rather than replaying a
    // possibly-already-rotated-away one. The access token staying stale in
    // that failure case is the lesser problem: it only affects calls made
    // before the next boot.
    await _storage.write(key: _refreshKey, value: refreshToken);
    await _storage.write(key: _key, value: accessToken);
  }

  @override
  Future<void> clearSession() async {
    // Refresh token first (mirrors `saveSession`'s ordering rationale):
    // it's the one `restoreSession()` reads to decide whether to call
    // `auth-refresh` at all, so clearing it first guarantees a
    // backend-confirmed-dead token is never retried even if the
    // access-token delete below then fails.
    await _storage.delete(key: _refreshKey);
    await _storage.delete(key: _key);
  }
}
